package com.hospital.dao;
import com.hospital.model.Appointment;import com.hospital.util.DBConnection;import java.sql.*;import java.time.*;import java.util.*;
public class AppointmentDAO {
 public long book(long patient,long doctor,LocalDateTime start,LocalDateTime end,String reason,long user)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{
   // Lock doctor row so two simultaneous booking transactions serialize before checking overlaps.
   try(PreparedStatement lock=c.prepareStatement("SELECT doctor_id FROM doctors WHERE doctor_id=? AND active=1 FOR UPDATE")){lock.setLong(1,doctor);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new SQLException("Active doctor not found.");}}
   try(PreparedStatement patientCheck=c.prepareStatement("SELECT patient_id FROM patients WHERE patient_id=? AND active=1")){patientCheck.setLong(1,patient);try(ResultSet r=patientCheck.executeQuery()){if(!r.next())throw new SQLException("Active patient not found.");}}
   try(PreparedStatement availability=c.prepareStatement("SELECT 1 FROM doctor_availability WHERE doctor_id=? AND active=1 AND day_of_week=? AND start_time<=? AND end_time>=?")){availability.setLong(1,doctor);availability.setInt(2,start.getDayOfWeek().getValue());availability.setTime(3,Time.valueOf(start.toLocalTime()));availability.setTime(4,Time.valueOf(end.toLocalTime()));try(ResultSet r=availability.executeQuery()){if(!r.next())throw new SQLException("Appointment is outside the doctor's configured working hours.");}}
   try(PreparedStatement clash=c.prepareStatement("SELECT appointment_id FROM appointments WHERE doctor_id=? AND status='SCHEDULED' AND start_at<? AND end_at>? FOR UPDATE")){clash.setLong(1,doctor);clash.setTimestamp(2,Timestamp.valueOf(end));clash.setTimestamp(3,Timestamp.valueOf(start));try(ResultSet r=clash.executeQuery()){if(r.next())throw new SQLException("Doctor already has an overlapping appointment.");}}
   long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,start_at,end_at,reason,created_by) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patient);p.setLong(2,doctor);p.setTimestamp(3,Timestamp.valueOf(start));p.setTimestamp(4,Timestamp.valueOf(end));p.setString(5,reason);p.setLong(6,user);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}
   c.commit();return id;
  }catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException("Appointment booking failed.",e);}finally{c.setAutoCommit(true);}}
 }
 public List<String> list(LocalDate date,Long doctor)throws SQLException{String sql="SELECT a.appointment_id,a.start_at,a.status,p.full_name,d.full_name FROM appointments a JOIN patients p USING(patient_id) JOIN doctors d USING(doctor_id) WHERE (? IS NULL OR DATE(a.start_at)=?) AND (? IS NULL OR a.doctor_id=?) ORDER BY a.start_at LIMIT 200";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(date==null){p.setNull(1,Types.DATE);p.setNull(2,Types.DATE);}else{p.setDate(1,java.sql.Date.valueOf(date));p.setDate(2,java.sql.Date.valueOf(date));}if(doctor==null){p.setNull(3,Types.BIGINT);p.setNull(4,Types.BIGINT);}else{p.setLong(3,doctor);p.setLong(4,doctor);}try(ResultSet r=p.executeQuery()){List<String>x=new ArrayList<>();while(r.next())x.add(String.format("%d | %s | %s | patient %s | doctor %s",r.getLong(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getString(5)));return x;}}}
 public void changeStatus(long id,String status,Long doctor)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET status=? WHERE appointment_id=? AND status='SCHEDULED' AND (? IS NULL OR doctor_id=?)")){p.setString(1,status);p.setLong(2,id);if(doctor==null){p.setNull(3,Types.BIGINT);p.setNull(4,Types.BIGINT);}else{p.setLong(3,doctor);p.setLong(4,doctor);}if(p.executeUpdate()==0)throw new SQLException("Scheduled appointment not found or not assigned to your account.");}}
 public void reschedule(long id,long doctor,LocalDateTime start,LocalDateTime end)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement lock=c.prepareStatement("SELECT doctor_id FROM doctors WHERE doctor_id=? AND active=1 FOR UPDATE")){lock.setLong(1,doctor);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new SQLException("Active doctor not found.");}}try(PreparedStatement availability=c.prepareStatement("SELECT 1 FROM doctor_availability WHERE doctor_id=? AND active=1 AND day_of_week=? AND start_time<=? AND end_time>=?")){availability.setLong(1,doctor);availability.setInt(2,start.getDayOfWeek().getValue());availability.setTime(3,Time.valueOf(start.toLocalTime()));availability.setTime(4,Time.valueOf(end.toLocalTime()));try(ResultSet r=availability.executeQuery()){if(!r.next())throw new SQLException("Appointment is outside the doctor working hours.");}}try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM appointments WHERE doctor_id=? AND status='SCHEDULED' AND appointment_id<>? AND start_at<? AND end_at>? FOR UPDATE")){p.setLong(1,doctor);p.setLong(2,id);p.setTimestamp(3,Timestamp.valueOf(end));p.setTimestamp(4,Timestamp.valueOf(start));try(ResultSet r=p.executeQuery()){if(r.next())throw new SQLException("Doctor already has an overlapping appointment.");}}try(PreparedStatement p=c.prepareStatement("UPDATE appointments SET doctor_id=?,start_at=?,end_at=? WHERE appointment_id=? AND status='SCHEDULED'")){p.setLong(1,doctor);p.setTimestamp(2,Timestamp.valueOf(start));p.setTimestamp(3,Timestamp.valueOf(end));p.setLong(4,id);if(p.executeUpdate()==0)throw new SQLException("Scheduled appointment not found.");}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
}
